import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import type { GameCase, User } from '@/types';
import { CaseUserStatus } from '@/types';
import { fetchCases } from '@/services/api';
import { logout } from '@/services/auth';
import CaseBriefingModal from '@/components/CaseBriefingModal/CaseBriefingModal';
import styles from './MainMenu.module.css';

export default function MainMenu() {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [user, setUser] = useState(null);
  const [selectedCase, setSelectedCase] = useState(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('auth_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const { data: cases = [], isLoading, error } = useQuery({
    queryKey: ['cases'],
    queryFn: async () => {
      const result = await fetchCases();
      if (!result.isSuccess) throw new Error(result.errorMessage);

      localStorage.setItem('auth_user', JSON.stringify(result.value.user));
      setUser(result.value.user);
      return result.value.cases;
    }
  });

  const handleLogout = () => {
    logout();
    queryClient.clear();
    window.dispatchEvent(new CustomEvent('auth:unauthorized'));
  };

  if (isLoading) return 
{t('pages.mainMenu.decrypting')};
  if (error) return 
{error instanceof Error ? error.message : t('pages.mainMenu.failedToLoad')};

  const heroCase = cases.length > 0 ? cases[0] : null;
  const rosterCases = cases.length > 1 ? cases.slice(1) : [];

  const getCaseStatusInfo = (gameCase: GameCase) => {
    const isSolved = gameCase.user_status === CaseUserStatus.SolvedPerfect ||
                     gameCase.user_status === CaseUserStatus.SolvedPartial;
    const isFailed = gameCase.user_status === CaseUserStatus.FailedNoProof ||
                     gameCase.user_status === CaseUserStatus.FailedIncomplete ||
                     gameCase.user_status === CaseUserStatus.FailedStrikes;
    return { isSolved, isFailed };
  };

  return (


      {/* 1. Floating Glass Header */}




{t('pages.mainMenu.activeInvestigations')}




          {user?.is_admin && (
             navigate('/admin')}
            >
              {t('pages.mainMenu.systemOversight')}

          )}

          {user && (



                {t('pages.mainMenu.agent')} {user.username}

              {user.XP} {t('pages.mainMenu.xp')}
              {t('pages.mainMenu.logout')}

          )}



      {/* 2. Cinematic Hero Section (First Case) */}
      {heroCase && (

 setSelectedCase(heroCase)}
        >









              ★ {t('pages.mainMenu.featuredDossier') || 'Priority Investigation'}



{heroCase.title}



              {heroCase.story}




              {t('components.caseCard.minXp')} {heroCase.min_player_XP}
              {t('components.caseCard.reward')} {heroCase.XP_on_solve} {t('components.caseCard.xp')}




               {
                  e.stopPropagation();
                  setSelectedCase(heroCase);
                }}
              >
                {t('components.caseBriefingModal.examineEvidence') || 'Access Dossier'} →




      )}

      {/* 3. Roster Cards (Remaining Cases) */}
      {rosterCases.length > 0 && (





{t('pages.mainMenu.activeInvestigations')}

{t('pages.mainMenu.selectDossier')}




            {rosterCases.map((gameCase) => {
              const { isSolved, isFailed } = getCaseStatusInfo(gameCase);
              return (

 setSelectedCase(gameCase)}
                >







                    {isSolved && (


                        {t('components.caseCard.caseClosed')}

                    )}

                    {isFailed && (



                          {t('components.caseCard.failed')}


                    )}



                      {t('components.caseCard.minXp')} {gameCase.min_player_XP}
                      {t('components.caseCard.reward')} {gameCase.XP_on_solve} {t('components.caseCard.xp')}





{gameCase.title}

{gameCase.story}



              );
            })}


      )}

      {selectedCase && (
         setSelectedCase(null)}
        />
      )}

  );
}

import { type Result, success, failure } from '@/utils/Result';
import { getToken } from './auth';

const BASE_URL = import.meta.env.VITE_API_URL ?? 'http://localhost:8000/api';
const API_BASE_URL = `${BASE_URL}/admin`;

const handleUnauthorized = () => {
  window.dispatchEvent(new CustomEvent('auth:unauthorized'));
};

/**
 * Centralized API Request Handler
 */
const adminRequest = async (endpoint: string, options: RequestInit): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      ...options,
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`,
        ...options.headers,
      },
    });

    if (!response.ok) {
      if (response.status === 401 || response.status === 403) handleUnauthorized();
      const data = await response.json().catch(() => ({}));
      return failure(data.message || `Operation failed (${response.status}).`);
    }

    return success(await response.json());
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

