  exhibits: BallisticsExhibit[];
  firearm_specs: string;
  microscopic_analysis: string;
  trajectory_range?: string;
  conclusion: string;
  examiner_name: string;
  investigator_notes?: string;
  caliber?: string;
  rifling_pattern?: string;
  firing_distance?: string;
  chain_of_custody?: ChainOfCustodyInfo;
}

export interface DnaMetadata {
  sample_type: string;
  match_probability: string;
  identified_person: string | null;
  lab_technician?: string;
  extraction_method?: string;
  loci_profile_summary?: string;
  lab_notes?: string;
}

export interface DigitalForensicsMetadata {
  device_type: string;
  extraction_method: string;
  recovered_data: string;
}

export interface TraceMetadata {
  material_type: string;
  origin_source: string;
}

export type ForensicEvidence =
  | (BaseEvidence & { evidence_type: 'forensic'; sub_type: 'autopsy'; metadata: AutopsyMetadata })
  | (BaseEvidence & { evidence_type: 'forensic'; sub_type: 'ballistics'; metadata: BallisticsMetadata })
  | (BaseEvidence & { evidence_type: 'forensic'; sub_type: 'dna'; metadata: DnaMetadata })
  | (BaseEvidence & { evidence_type: 'forensic'; sub_type: 'digital_forensics'; metadata: DigitalForensicsMetadata })
  | (BaseEvidence & { evidence_type: 'forensic'; sub_type: 'trace_analysis'; metadata: TraceMetadata });

import type { BaseEvidence } from './base';
import type { ForensicEvidence } from './forensic';
import type { DocumentEvidence } from './document';

export * from './base';
export * from './forensic';
export * from './document';

// 1. STRICT TESTIMONY TYPE
export interface TranscriptLine {
  type: 'q' | 'a';
  speaker: string;
  text: string;
}

export interface TestimonyMetadata {
  agency?: string;
  title?: string;
  date?: string;
  case_number?: string;
  subject_name?: string;
  interviewer?: string;
  context?: string;
  transcript?: TranscriptLine[] | string;
}

export interface TestimonyEvidence extends BaseEvidence {
  evidence_type: 'testimony';
  sub_type?: null;
  metadata: TestimonyMetadata;
}

// 2. STRICT MEDIA TYPE (For Audio & Images)
export interface MediaEvidence extends BaseEvidence {
  evidence_type: 'image' | 'audio';
  sub_type?: null;
  metadata?: Record | null;
}

// 3. THE MASTER TYPE
export type Evidence = ForensicEvidence | DocumentEvidence | TestimonyEvidence | MediaEvidence;

export type Result =
  | { isSuccess: true; value: T; errorMessage?: never }
  | { isSuccess: false; value?: never; errorMessage: E };

export const success = (value: T): Result => ({
  isSuccess: true,
  value,
});

export const failure = (errorMessage: E): Result => ({
  isSuccess: false,
  errorMessage,
});

import DOMPurify from 'dompurify';

const PURIFY_CONFIG = {
  ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p', 'span', 'br', 'ul', 'li', 'ol', 'div'],
  ALLOWED_ATTR: ['class', 'href', 'target'],
};

/**
 * Sanitizes dirty HTML strings to prevent XSS attacks.
 * Preserves specific safe tags and attributes required for immersive formatting.
 */
export const sanitizeHtml = (dirty: string): string => {
  return DOMPurify.sanitize(dirty, PURIFY_CONFIG);
};
